package hu.boltseged.shipping; import org.springframework.http.HttpStatusCode; import java.util.*; public class DhlApiException extends RuntimeException {private final HttpStatusCode status;private final List<String> messages;public DhlApiException(HttpStatusCode s,List<String> m){super(m.isEmpty()?"DHL request failed":m.getFirst());status=s;messages=List.copyOf(m);}public HttpStatusCode status(){return status;}public List<String> messages(){return messages;}}
